const clientTime = Date.now() / 1000;
const currentYear = new Date().getFullYear();
const timeOffset = serverTime - clientTime + 60;
const accurateTime = () => (Date.now() / 1000) + timeOffset;
window[siteName + atob('Q29uZmln')] = {"c": serverTime, "t": atob(configToken), "v": version, "e": serverTime + 3600};
